') }}">@csrf<input type="hidden" name="product_id" value="{{ $product->id }}"><input type="hidden" name="quantity" value="0"><button class="cart-remove" type="submit" name="action" value="remove" aria-label="Xóa {{ $product->name }} khỏi giỏ">Xóa</button></form></div></div><strong class="cart-price">{{ number_format($product->price*$cart[$product->id],0,',','.') }} ₫</strong></div>@endforeach</div><div class="col-lg-4"><aside class="summary-card"><h2>Giỏ hàng của bạn</h2><div class="summary-line total"><span>Tổng giá niêm yết</span><strong>{{ number_format($total,0,',','.') }} ₫</strong></div><p class="demo-note">Giá đã gồm VAT. Nhận tại kho không tính phí giao.</p>@auth @if(auth()->user()->role==='customer')<section class="cart-checkout-option"><span class="eyebrow">Mua với giá niêm yết</span><h3>Nhận tại kho</h3><form method="post" action="{{ route('pickup-orders.store') }}">@csrf<label class="form-label" for="pickupWarehouse">Kho nhận hàng</label><select class="form-select" id="pickupWarehouse" name="warehouse_id" data-validation-message="Vui lòng chọn kho nhận hàng trước khi đặt hàng." required><option value="">Chọn kho</option>@foreach($warehouses as $warehouse)<option value="{{ $warehouse->id }}" @selected(old('warehouse_id') == $warehouse->id)>{{ $warehouse->name }}{{ $warehouse->address ? ' · '.$warehouse->address : '' }}</option>@endforeach</select><button class="btn-editorial dark" type="submit" @disabled($warehouses->isEmpty() || !$canPickup)>Đặt hàng nhận tại kho</button></form>@if(!$canPickup)<p class="demo-note">Giỏ có vật liệu cần nhân viên xác nhận giá. Hãy gửi yêu cầu báo giá bên dưới.</p>@elseif($warehouses->isEmpty())<p class="demo-note">Chưa có kho nhận hàng. Bạn có thể gửi yêu cầu báo giá bên dưới.</p>@endif</section><section class="cart-checkout-option"><span class="eyebrow">Yêu cầu báo giá</span><h3>Báo giá vật liệu</h3><form method="post" action="{{ route('quotes.request') }}">@csrf<label class="form-label" for="deliveryAddress">Địa chỉ công 